// Prepare HTML formatted email body from incoming resource payload
const payload = $input.first().json;

const recipient = payload.recipient || 'student@university.edu';
const topic = payload.topic || 'Academic Learning Plan';
const proficiency = payload.proficiency || 'Beginner';
const goal = payload.learning_goal || 'Exam Prep';
const score = payload.overall_quality_score || 90;
const resources = payload.resources || [];

let resourceHtml = '';
for (const r of resources) {
  resourceHtml += `
    <div style="margin-bottom:14px; padding:12px; border:1px solid #e2e8f0; border-radius:8px; background:#ffffff;">
      <div style="font-size:15px; font-weight:bold; color:#0f172a;">#${r.rank} ${r.title} <span style="font-size:11px; color:#64748b; text-transform:uppercase;">[${r.type}]</span></div>
      <p style="margin:6px 0; font-size:13px; color:#475569;">${r.why_it_fits}</p>
      <div style="font-size:12px; color:#2563eb;">
        ${r.url ? `<a href="${r.url}">Access Resource</a> (${r.link_status === 'verified_200' ? '✓ Verified 200 OK' : '⚠ Flagged'})` : `<a href="${r.fallback_search_url}">Search Official Source</a> (Anti-hallucination safe)`}
        <span style="color:#64748b; margin-left:12px;">Est: ${r.estimated_time}</span>
      </div>
    </div>
  `;
}

const htmlBody = `
  <div style="font-family:sans-serif; max-width:600px; margin:0 auto; padding:20px; background:#f8fafc;">
    <h2 style="color:#0f172a;">Your Personalized Learning Roadmap</h2>
    <p style="color:#64748b;">Topic: <strong>${topic}</strong> (${proficiency} Level)</p>
    <p style="color:#64748b;">Goal: ${goal}</p>
    <p style="color:#16a34a; font-weight:bold;">Quality Score: ${score}/100</p>
    <hr style="border:none; border-top:1px solid #cbd5e1; margin:16px 0;"/>
    ${resourceHtml}
    <p style="font-size:11px; color:#94a3b8; margin-top:20px;">Generated by Personalized Learning Resource Recommender.</p>
  </div>
`;

const txId = 'n8n_tx_' + Date.now().toString(36);

return [{
  json: {
    recipient,
    subject: `Personalized Curriculum: ${topic}`,
    htmlBody,
    txId,
    timestamp: new Date().toISOString()
  }
}];
